class _FeedState extends State<Feed> {
  final controller = ScrollController();

  @override
  void initState() {
    super.initState();
    // ❌ a fresh closure — nothing will ever match it
    controller.addListener(() => _onScroll());
  }

  @override
  void dispose() {
    // ❌ a second, different closure: removes nothing, leaks this State
    controller.removeListener(() => _onScroll());
    controller.dispose();
    super.dispose();
  }

  void _onScroll() => setState(() {});
}

// ✅ tear-off: the same value both times
class _FeedStateFixed extends State<Feed> {
  final controller = ScrollController();

  @override
  void initState() {
    super.initState();
    controller.addListener(_onScroll); // no parentheses — the function itself
  }

  @override
  void dispose() {
    controller.removeListener(_onScroll); // matches, detaches
    controller.dispose();
    super.dispose();
  }

  void _onScroll() => setState(() {});
}

